import i18n from 'i18next';

/**
 * NDLI Club Main Portal — i18n runtime (S4, M3 §4c code-split).
 *
 * Design:
 * - Keys are the NATURAL ENGLISH STRINGS themselves (generated by the S3 codemod),
 *   so the English UI needs zero resource entries: a missing key renders as-is.
 * - Every listed language has a REAL catalogue (flat map, keys = English strings):
 *   `hi.json` is curated Hindi; the other 18 are machine-drafted catalogues
 *   (review-pending), generated with protected tokens (IDs, dates, URLs,
 *   acronyms, emails) preserved byte-exact.
 * - Catalogues are LOADED ON DEMAND (one lazy chunk per language, ~70KB raw
 *   each): the initial bundle carries EN only, keeping public-page JS inside
 *   the 150KB gzip budget (BRIEF_M3 §4c). Switching a language downloads its
 *   catalogue exactly once, then registers it with i18next.
 * - keySeparator/nsSeparator are DISABLED on purpose: our keys are prose and
 *   contain dots ("0.4 seconds"), colons ("(AISHE:"), and slashes ("NAD-ABC"),
 *   which must never be parsed as nesting/namespace syntax.
 * - RTL: Urdu and Sindhi (Perso-Arabic) set `dir=rtl` on <html> at switch time.
 */

export const SUPPORTED_LANG_CODES = [
  'en', 'hi', 'as', 'bn', 'doi', 'gu', 'kn', 'kok', 'mai', 'ml',
  'mr', 'ne', 'or', 'pa', 'sa', 'sat', 'sd', 'ta', 'te', 'ur',
];

const RTL_LANG_CODES = ['ur', 'sd'];

type Catalog = Record<string, string>;

/** One dynamic-import chunk per catalogue (never in the initial bundle). */
const CATALOG_LOADERS: Record<string, () => Promise<{ default: Catalog }>> = {
  hi: () => import('./i18n/hi.json'),
  as: () => import('./i18n/as.json'),
  bn: () => import('./i18n/bn.json'),
  doi: () => import('./i18n/doi.json'),
  gu: () => import('./i18n/gu.json'),
  kn: () => import('./i18n/kn.json'),
  kok: () => import('./i18n/kok.json'),
  mai: () => import('./i18n/mai.json'),
  ml: () => import('./i18n/ml.json'),
  mr: () => import('./i18n/mr.json'),
  ne: () => import('./i18n/ne.json'),
  or: () => import('./i18n/or.json'),
  pa: () => import('./i18n/pa.json'),
  sa: () => import('./i18n/sa.json'),
  sat: () => import('./i18n/sat.json'),
  sd: () => import('./i18n/sd.json'),
  ta: () => import('./i18n/ta.json'),
  te: () => import('./i18n/te.json'),
  ur: () => import('./i18n/ur.json'),
};

void i18n.init({
  // English needs no resources: keys ARE the English strings.
  resources: { en: { translation: {} } },
  lng: 'en',
  fallbackLng: 'en',
  supportedLngs: SUPPORTED_LANG_CODES,
  keySeparator: false,
  nsSeparator: false,
  interpolation: { escapeValue: false },
  returnEmptyString: false,
  returnNull: false,
});

/** Translate one natural-key string. Missing keys fall back to the key itself (English). */
export function t(key: string, opts?: Record<string, unknown>): string {
  return i18n.t(key, opts as never) as unknown as string;
}

/**
 * Switch UI language; keep <html lang> (WCAG 3.1.1) and <html dir> in sync.
 * Loads the catalogue chunk on first use (M3 §4c), then switches. Callers
 * re-render after awaiting this.
 */
export async function changeLanguage(code: string): Promise<void> {
  if (code !== 'en' && !i18n.hasResourceBundle(code, 'translation')) {
    const load = CATALOG_LOADERS[code];
    if (load) {
      const mod = await load();
      i18n.addResourceBundle(code, 'translation', mod.default, true, true);
    }
  }
  await i18n.changeLanguage(code);
  if (typeof document !== 'undefined') {
    document.documentElement.lang = code;
    document.documentElement.dir = RTL_LANG_CODES.includes(code) ? 'rtl' : 'ltr';
  }
}

export default i18n;
